.execute(
 "INSERT INTO site (name, prefix, created_at) VALUES (?1,?2,?3)",
 params![s.name(), s.prefix(), now_text()],
 )
.map_err(sql_error)?;
 // Pre-create a `tickets_new` table so the CREATE TABLE in migration 0002
 // fails partway through the rebuild.
