.query_row("SELECT COUNT(*) FROM tickets WHERE id = 'drk-1'", [], |r| {
 r.get(0)
 })
.map_err(sql_error)?;
 assert_eq!(count, 1);
 }

 // After fixing, migration can succeed.
 let substrate = NativeSubstrate::open(config, site_for_v1()).await?;
 let t = substrate
.get_ticket(&ticket_id("drk-1")?)
.await?
.expect("preserved");
